<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$a=(string)($_POST['action']??'');if($id&&in_array($a,['approve','reject','delete'],true)){if($a==='delete')db()->prepare('DELETE FROM reviews WHERE id=:id')->execute([':id'=>$id]);else {db()->prepare('UPDATE reviews SET status=:s WHERE id=:id')->execute([':s'=>$a==='approve'?'approved':'rejected',':id'=>$id]);if($a==='approve'){$n=db()->prepare('SELECT l.owner_user_id,l.name FROM reviews r JOIN listings l ON l.id=r.listing_id WHERE r.id=:id');$n->execute([':id'=>$id]);if($owner=$n->fetch())if((int)$owner['owner_user_id']>0)notify_user((int)$owner['owner_user_id'],'A review was published','A new approved review is now visible for '.(string)$owner['name'].'.','owner/marketplace.php');}}flash('success',$a==='delete'?'Review deleted.':'Review status updated.');}redirect(app_path('admin/reviews.php'));}
$status=(string)($_GET['status']??'pending');$where=in_array($status,['pending','approved','rejected'],true)?'WHERE r.status=:status':'';$s=db()->prepare('SELECT r.*,l.name listing_name,l.slug FROM reviews r JOIN listings l ON l.id=r.listing_id '.$where.' ORDER BY r.created_at DESC');if($where)$s->execute([':status'=>$status]);else$s->execute();$rows=$s->fetchAll();$adminTitle='Review moderation';include __DIR__.'/_header.php';?>
<div class="admin-panel"><div class="admin-filter"><div class="filter-tabs"><?php foreach(['pending','approved','rejected'] as $x): ?><a class="filter-chip <?= $status===$x?'selected':'' ?>" href="<?= app_path('admin/reviews.php?status='.$x) ?>"><?= ucfirst($x) ?></a><?php endforeach; ?></div></div><?php if($rows): ?><div class="moderation-list"><?php foreach($rows as $r): ?><article class="moderation-item"><div class="review-avatar"><?= h(text_upper(text_substr($r['reviewer_name'],0,1))) ?></div><div class="moderation-copy"><div class="review-top"><strong><?= h($r['reviewer_name']) ?></strong><span class="review-stars"><?= str_repeat('★',(int)$r['rating']) ?><span><?= str_repeat('☆',5-(int)$r['rating']) ?></span></span></div><p><?= nl2br(h($r['comment'])) ?></p><small>For <a href="<?= app_path('index.php?listing='.rawurlencode($r['slug'])) ?>" target="_blank"><?= h($r['listing_name']) ?></a> · <?= h(format_date($r['created_at'])) ?> · <span class="status-pill status-<?= h($r['status']) ?>"><?= h(ucfirst($r['status'])) ?></span></small></div><div class="moderation-actions"><?php if($r['status']!=='approved'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="approve"><button class="table-action">Approve</button></form><?php endif; ?><?php if($r['status']!=='rejected'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="reject"><button class="table-action">Reject</button></form><?php endif; ?><form method="post" onsubmit="return confirm('Delete this review?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="delete"><button class="table-action danger-text">Delete</button></form></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span><i class="fa-regular fa-face-smile"></i></span><h3>Nothing to review here</h3><p>There are no <?= h($status) ?> reviews right now.</p></div><?php endif; ?></div><?php include __DIR__.'/_footer.php';?>
